const e=[{id:"sv-5-626",phase:5,topic:"5.1.3",qtype:"concept",difficulty:1,stem:"Who is credited with developing **poka-yoke** as part of the Toyota Production System?",options:["Shigeo Shingo","Taiichi Ohno","W. Edwards Deming","Walter Shewhart"],answer:0,hint:"Mistake proofing and SMED are both linked to the same Toyota engineer.",steps:[{title:"Key idea",body:"Poka-yoke and source inspection were developed and popularised by **Shigeo Shingo** within the Toyota Production System."},{title:"Eliminate look-alikes",body:"Ohno = TPS/JIT, Deming = PDSA, Shewhart = control charts."}],final:"Shingo developed poka-yoke → answer **A**",whyWrong:["","Incorrect — Ohno is credited with the wider Toyota Production System and just-in-time, not with poka-yoke devices.","Incorrect — Deming is linked to PDSA and statistical quality in post-war Japan, not to mistake-proofing devices.","Incorrect — Shewhart developed the control chart in 1924; that is SPC, not mistake proofing."],trap:"Shingo and Ohno are often swapped: Shingo = poka-yoke and SMED.",bookRef:"Syllabus 5.1.3"},{id:"sv-5-627",phase:5,topic:"5.1.3",qtype:"concept",difficulty:1,stem:"Which poka-yoke **regulatory function** stops the process as soon as an abnormality is sensed?",options:["Contact function","Control function","Fixed-value function","Warning function"],answer:1,hint:"Setting method = how it senses; regulatory function = what it does next.",steps:[{title:"Key idea",body:"A poka-yoke's regulatory function is either **control** (shut-down) or **warning** (alert)."},{title:"Apply",body:"Stopping the process is the control function, the stronger of the two."}],final:"Stopping the process = control function → answer **B**",whyWrong:["Incorrect — contact is a setting method (how the abnormality is sensed), not a regulatory function.","","Incorrect — fixed-value is a setting method that counts items or actions, not a response.","Incorrect — a warning function only alerts with a light or sound; the process can carry on."],bookRef:"Syllabus 5.1.3"},{id:"sv-5-628",phase:5,topic:"5.1.3",qtype:"concept",difficulty:3,stem:"What is the difference between a poka-yoke **setting method** and its **regulatory function**?",options:["The setting method is how the abnormality is sensed; the function is whether it stops or warns","The setting method is whether it stops or warns; the function is how the abnormality is sensed","The setting method is the FMEA rating it lowers; the function is the control-plan owner","The setting method is the cost of the device; the function is how often it is tested"],answer:0,hint:"Contact / fixed-value / motion-step vs control / warning.",steps:[{title:"Key idea",body:"Setting methods (contact, fixed-value, motion-step) describe **how** the device senses the error."},{title:"Apply",body:"Regulatory functions (control or warning) describe **what happens** once it is sensed."}],final:"Sense vs respond → answer **A**",whyWrong:["","Incorrect — this reverses the two terms.","Incorrect — FMEA ratings and owners are control-plan details, not poka-yoke classifications.","Incorrect — cost and test frequency are practical details, not the two ways devices are classified."],bookRef:"Syllabus 5.1.3"},{id:"sv-5-629",phase:5,topic:"5.1.3",qtype:"concept",difficulty:1,stem:"In a service workflow, what is an **interlock**?",options:["A report that lists errors found at the end of each day","A checklist that agents are asked to read before each call","A rule that stops a step starting until the required conditions are met","A chart that signals when the error rate shifts"],answer:2,hint:"Interlocks block; reports, checklists and charts do not.",steps:[{title:"Key idea",body:"An interlock prevents a step from starting until prior steps or conditions are complete (a motion-step device)."},{title:"Eliminate",body:"Reports, checklists and charts all depend on someone noticing and acting."}],final:"Interlock = block until conditions are met → answer **C**",whyWrong:["Incorrect — a daily error report is after-the-fact inspection, not a device in the process.","Incorrect — a checklist relies on people remembering to use it; it does not block anything.","","Incorrect — a chart is SPC; it signals a shift but does not stop the step."],bookRef:"Syllabus 5.1.3"},{id:"sv-5-630",phase:5,topic:"5.1.3",qtype:"concept",difficulty:2,stem:"Why did Shingo replace the earlier term *baka-yoke* (fool-proofing) with *poka-yoke*?",options:["To stress that devices protect people from slips that every person makes","To stress that only machines, not people, should make the product","To stress that careless operators must be replaced by automation","To stress that errors are rare and can be handled by inspection"],answer:0,hint:"Think about what 'fool' implies about the worker.",steps:[{title:"Key idea",body:"Poka-yoke assumes people are **human**: slips are inevitable, so the design should catch them."},{title:"Apply",body:"'Fool-proofing' blamed the worker, so the term was changed to inadvertent-error proofing."}],final:"Devices protect people from inevitable slips → answer **A**",whyWrong:["","Incorrect — poka-yoke supports people at work; it does not remove them from the process.","Incorrect — the change was made precisely to avoid blaming operators as careless or foolish.","Incorrect — poka-yoke assumes errors are inevitable, and inspection is ranked below mistake proofing."],bookRef:"Syllabus 5.1.3"},{id:"sv-5-631",phase:5,topic:"5.1.3",qtype:"concept",difficulty:2,stem:"How is poka-yoke applied to a step where the error **cannot** be designed out?",options:["By detecting the error at once and stopping the process before the defect moves on","By adding a written instruction that reminds people to avoid the error","By sampling the output every hour and plotting it on a control chart","By widening the specification so that the error no longer counts as a defect"],answer:0,hint:"If prevention is impossible, what is the next use of poka-yoke?",steps:[{title:"Key idea",body:"Poka-yoke has two uses: prevention (Type 1) and, when that is not possible, detection that shuts down (Type 2)."},{title:"Apply",body:"Detect immediately and stop, so the defect never reaches the next step."}],final:"Fallback = detect and stop → answer **A**",whyWrong:["","Incorrect — an SOP alone is the weakest control and is not mistake proofing.","Incorrect — SPC detects shifts in the output; it does not stop each error at the step.","Incorrect — widening the specification hides defects; it does not control the error."],bookRef:"Book p. 522"},{id:"sv-5-632",phase:5,topic:"5.1.3",qtype:"concept",difficulty:1,stem:"Which is an example of a **fixed-value** poka-yoke in a contact centre?",options:["The account field rejects any number that fails the check-digit format","The wrap-up screen cannot close until all four disposition fields are filled","The refund screen opens only after the customer's identity check is passed","A laminated card at each desk lists the four disposition codes"],answer:1,hint:"Fixed-value = a set NUMBER of items or actions must be completed.",steps:[{title:"Key idea",body:"The fixed-value method checks that a **set number** of parts or actions has been completed."},{title:"Apply",body:"'All four fields filled' is a count check → fixed-value. Format = contact; order = motion-step."}],final:"A set number of fields → fixed-value → answer **B**",whyWrong:["Incorrect — checking an attribute such as format is the contact method.","","Incorrect — requiring one step before the next is the motion-step (sequence) method.","Incorrect — a reference card is a visual aid or SOP; it does not sense or stop the error."],bookRef:"Syllabus 5.1.3"},{id:"sv-5-633",phase:5,topic:"5.1.3",qtype:"concept",difficulty:3,stem:"Enteral-feeding syringes are made with connectors that physically **cannot fit** an intravenous line. How is this device classified?",options:["Detection device using the contact method","Prevention device using the motion-step method","Prevention device using the contact method","Detection device using the fixed-value method"],answer:2,hint:"Two questions: can the error still happen? What does the device sense?",steps:[{title:"Function",body:"The wrong connection cannot be made at all → **prevention** (Type 1)."},{title:"Method",body:"It works through physical shape → **contact** method."},{title:"Eliminate",body:"Detection and fixed-value/motion-step options each fail one of the two tests."}],final:"Shape makes the error impossible → prevention, contact → answer **C**",whyWrong:["Incorrect — a detection device lets the error happen and then catches it; here the wrong connection is impossible.","Incorrect — motion-step checks the order of steps; this device relies on physical shape.","","Incorrect — nothing is counted and nothing is caught afterwards; the shape blocks the error."],bookRef:"Syllabus 5.1.3"},{id:"sv-5-634",phase:5,topic:"5.1.3",qtype:"concept",difficulty:2,stem:"What is the main limitation of a **detection**-type poka-yoke compared with a prevention-type device?",options:["The defect can still move forward to the next process step","It depends on an inspector sampling the output each hour","The error still occurs, so the item must be stopped and corrected","It cannot be recorded as a control in the control plan"],answer:2,hint:"Prevention: never created. Detection: created, but caught.",steps:[{title:"Key idea",body:"A Type 2 flag **detects** the error condition and shuts down so the defect does not move forward (p. 522)."},{title:"Apply",body:"The error has still happened, so rework or scrap remains; prevention (Type 1) avoids even that."}],final:"Detection still lets the error occur → answer **C**",whyWrong:["Incorrect — a detection device stops the defect moving forward; that is its purpose (Type 2 flag).","Incorrect — a poka-yoke senses automatically; hourly sampling describes SPC or audits.","","Incorrect — detection devices are recorded in the control plan like any other control."],bookRef:"Book p. 522"},{id:"sv-5-635",phase:5,topic:"5.1.3",qtype:"concept",difficulty:1,stem:"Which is an example of a **contact-method** poka-yoke in assembly?",options:["A jig that accepts the part only the right way round","A counter that checks six screws have been driven","A press that will not cycle until the guard is closed","A wall chart showing the correct assembly steps"],answer:0,hint:"Contact = the device senses a physical feature.",steps:[{title:"Key idea",body:"The contact method uses shape, size or position to confirm the correct item or orientation."},{title:"Apply",body:"A shaped jig senses the part's orientation → contact."}],final:"Shaped jig → contact → answer **A**",whyWrong:["","Incorrect — counting a set number of actions is the fixed-value method.","Incorrect — requiring one step before the next is the motion-step method.","Incorrect — a wall chart is a visual aid or SOP; it senses nothing and stops nothing."],bookRef:"Syllabus 5.1.3"},{id:"sv-5-636",phase:5,topic:"5.1.3",qtype:"concept",difficulty:2,stem:"Which statement about poka-yoke devices is CORRECT?",options:["A device must be automated to count as mistake proofing","Many effective devices are simple, such as a mandatory field or a shaped jig","A device mainly reduces the severity of a failure mode","A device removes the need to verify the control afterwards"],answer:1,hint:"Think of the cheapest devices you know.",steps:[{title:"Key idea",body:"Poka-yoke is about the design of the step, not the price: a drop-down, a template or a keyed connector can make an error impossible."},{title:"Eliminate",body:"Automation is not required, severity is not the rating it moves, and verification is still needed."}],final:"Simple, cheap devices work → answer **B**",whyWrong:["Incorrect — low-tech devices such as drop-downs, colour codes and jigs are classic poka-yokes.","","Incorrect — prevention lowers occurrence and detection lowers the detection rating; severity is unchanged.","Incorrect — devices must be checked periodically; a bypassed device is a silent failure."],bookRef:"Syllabus 5.1.3"},{id:"sv-5-637",phase:5,topic:"5.1.3",qtype:"concept",difficulty:2,stem:"Which statement about the mistake-proofing hierarchy (eliminate, replace, facilitate, detect, mitigate) is CORRECT?",options:["Mitigation is preferred to detection because it acts after the error has occurred","The higher levels change the design; the lower levels accept that the error exists","Facilitation removes the error-prone step from the process completely","Detection ranks above facilitation because it uses sensors rather than people"],answer:1,hint:"Read the hierarchy from top (best) to bottom (last resort).",steps:[{title:"Key idea",body:"Eliminate and replace redesign the step; facilitate makes errors less likely; detect and mitigate manage errors that still happen."},{title:"Apply",body:"So the higher levels change the design and the lower levels accept the error — the same logic as the book's ranking."}],final:"Higher levels redesign; lower levels manage the error → answer **B**",whyWrong:["Incorrect — acting later is weaker; mitigation only reduces the impact, so it is the last resort.","","Incorrect — removing the step completely is elimination; facilitation only makes the right action easier.","Incorrect — facilitation sits above detection because it reduces the chance of the error itself."],bookRef:"Syllabus 5.1.3"},{id:"sv-5-638",phase:5,topic:"5.1.3",qtype:"concept",difficulty:1,stem:"Which statement about the **contact** method of poka-yoke is CORRECT?",options:["It checks that a set number of parts or actions has been completed","It checks that the steps of a task are done in the correct order","It can be built in software, such as a check on an account-number format","It can only be built with physical parts such as jigs and connectors"],answer:2,hint:"Contact checks an attribute of the item.",steps:[{title:"Key idea",body:"Contact devices sense a feature: shape, size, position, colour or format."},{title:"Apply",body:"A format check on an account number senses an attribute, so it is a contact device in software."}],final:"Format checks are contact devices → answer **C**",whyWrong:["Incorrect — counting parts or actions is the fixed-value method.","Incorrect — enforcing the order of steps is the motion-step method.","","Incorrect — validation of an attribute such as format is a software contact device."],bookRef:"Syllabus 5.1.3"},{id:"sv-5-639",phase:5,topic:"5.1.3",qtype:"concept",difficulty:2,stem:"Which statement about poka-yoke in a service process is CORRECT?",options:["A free-text field checked later by a reviewer is a prevention device","Service poka-yokes are limited to warnings because people must decide","A system rule cannot be a poka-yoke because it is not a physical device","A drop-down list fed from validated master data can act as a prevention device"],answer:3,hint:"Can the wrong value be chosen at all?",steps:[{title:"Key idea",body:"If only valid choices are offered, the wrong entry **cannot** be made → prevention."},{title:"Eliminate",body:"Review is inspection; warnings and 'physical only' are misconceptions."}],final:"Valid-only choices prevent the error → answer **D**",whyWrong:["Incorrect — a later review is inspection; the error is made first and may be missed.","Incorrect — system rules can block an action completely, which is a control (shut-down) function.","Incorrect — software validations, interlocks and templates are standard service poka-yokes.",""],bookRef:"Book pp. 557–560"},{id:"sv-5-640",phase:5,topic:"5.1.3",qtype:"statements",difficulty:3,stem:`Which statements about poka-yoke setting methods are CORRECT?

1. The contact method checks a feature such as shape, size or position.
2. Each setting method can be built as a prevention or a detection device.
3. The fixed-value method checks that steps are done in the correct order.
4. The motion-step method checks that a set number of parts is used.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Contact = feature, fixed-value = number, motion-step = sequence.",steps:[{title:"Check each",body:"1 true. 2 true (e.g. a blocking mandatory field is fixed-value prevention; a counter that beeps is fixed-value detection). 3 and 4 swap the definitions."},{title:"Select",body:"The true pair is 1 and 2."}],final:"Statements 1 and 2 → answer **A**",whyWrong:["","Incorrect — statement 3 is false: order of steps is the motion-step method.","Incorrect — statements 3 and 4 swap the fixed-value and motion-step definitions.","Incorrect — statement 4 is false: a set number of parts is the fixed-value method."],bookRef:"Syllabus 5.1.3"},{id:"sv-5-641",phase:5,topic:"5.1.3",qtype:"statements",difficulty:2,stem:`Which statements about the thinking behind poka-yoke are CORRECT?

1. Poka-yoke assumes that people will make slips however well trained they are.
2. Inspecting every unit at the end of the line is the core of poka-yoke.
3. A detection device that stops the process is weaker than a warning light.
4. Errors should be stopped before they become defects that reach the customer.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Errors are inevitable; defects are not.",steps:[{title:"Check each",body:"1 true. 2 false (inspection is Type 3 containment). 3 false (shut-down beats warning). 4 true."},{title:"Select",body:"The true pair is 1 and 4."}],final:"Statements 1 and 4 → answer **D**",whyWrong:["Incorrect — statement 2 is false: end-of-line inspection finds defects after they are made.","Incorrect — statements 2 and 3 are both false.","Incorrect — statement 3 is false: a warning relies on someone reacting, so a stop is stronger.",""],bookRef:"Syllabus 5.1.3"},{id:"sv-5-642",phase:5,topic:"5.1.3",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

The [?] method of poka-yoke uses shape, size, position or a sensor to confirm the correct item or orientation.`,options:["contact","fixed-value","motion-step","warning"],answer:0,hint:"Which method senses a physical feature?",steps:[{title:"Key idea",body:"The contact method detects an abnormality through a physical or attribute feature."},{title:"Eliminate",body:"Fixed-value = count; motion-step = order; warning = response type."}],final:"Shape or position → contact → answer **A**",whyWrong:["","Incorrect — fixed-value checks that a set number of items or actions is complete.","Incorrect — motion-step checks that steps happen in the correct order.","Incorrect — a warning is a regulatory function (an alert), not a setting method."],bookRef:"Syllabus 5.1.3"},{id:"sv-5-643",phase:5,topic:"5.1.3",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

A prevention-type poka-yoke that makes the cause of a failure mode impossible lowers its FMEA [?] rating.`,options:["criticality","detection","occurrence","severity"],answer:2,hint:"Prevention changes how often the cause happens.",steps:[{title:"Key idea",body:"Prevention removes or nearly removes the cause, so the cause happens less often → **occurrence** falls."},{title:"Eliminate",body:"Detection devices lower the detection rating; severity stays the same unless the design changes the effect."}],final:"Prevention lowers occurrence → answer **C**",whyWrong:["Incorrect — criticality is not one of the three FMEA ratings used for the RPN.","Incorrect — the detection rating is lowered by a detection device that catches the failure.","","Incorrect — severity describes the effect, which is unchanged if the failure did happen."],bookRef:"Book pp. 133, 522"},{id:"sv-5-644",phase:5,topic:"5.1.3",qtype:"missing-word",difficulty:3,stem:`Identify the missing word in the following sentence.

Shingo argued that [?] inspection, which checks the conditions that cause errors at the moment they occur, stops defects from being made at all.`,options:["final","informative","judgment","source"],answer:3,hint:"Inspect the cause, not the product.",steps:[{title:"Key idea",body:"**Source inspection** looks at the error condition itself, at the point where it happens."},{title:"Eliminate",body:"Final and judgment inspection sort output; informative inspection reports defects back upstream."}],final:"Checking the cause at the moment → source → answer **D**",whyWrong:["Incorrect — final inspection checks finished output, after the defect has been made.","Incorrect — informative inspection feeds back data on defects already made to the earlier step.","Incorrect — judgment inspection sorts good from bad output; it finds defects, it does not stop them.",""],bookRef:"Syllabus 5.1.3"},{id:"sv-5-645",phase:5,topic:"5.1.3",qtype:"not-except",difficulty:1,stem:"Which is NOT one of Shingo's poka-yoke setting methods?",options:["Contact method","Fixed-value method","Motion-step method","Random-sampling method"],answer:3,hint:"Name the three methods; the fourth option is an outsider from SPC.",steps:[{title:"Key idea",body:"The three setting methods are contact, fixed-value and motion-step."},{title:"Apply",body:"Random sampling belongs to SPC and audits, which depend on sampling outputs."}],final:"Random sampling is not a setting method → answer **D**",whyWrong:["Incorrect — contact is a genuine method: it senses shape, size or position.","Incorrect — fixed-value is a genuine method: it checks a set number of items or actions.","Incorrect — motion-step is a genuine method: it checks the order of steps.",""],bookRef:"Syllabus 5.1.3"},{id:"sv-5-646",phase:5,topic:"5.1.3",qtype:"not-except",difficulty:3,stem:"Which is NOT an example of defect prevention?",options:["Negotiating wider specification limits with the customer","Mistake proofing the order-entry screen","Applying robust design to the service","Designing a connector that fits only one way"],answer:0,hint:"Which option changes the target instead of the process?",steps:[{title:"Key idea",body:"Defect prevention stops errors happening: the book's quiz names poka-yoke and robust design (p. 583)."},{title:"Apply",body:"Widening the spec relabels output as good; the process still makes the same errors."}],final:"Wider specs do not prevent errors → answer **A**",whyWrong:["","Incorrect — mistake proofing is named by the book as defect prevention.","Incorrect — robust design is named by the book as defect prevention.","Incorrect — a one-way connector is a contact-method prevention poka-yoke."],trap:"Changing the specification hides defects on paper; it does not prevent them.",bookRef:"Book p. 583"},{id:"sv-5-647",phase:5,topic:"5.1.3",qtype:"not-except",difficulty:3,stem:"A detection device is added to a failure mode in the FMEA. Which element is NOT normally reduced by this change?",options:["Detection rating","Severity rating","Risk priority number","Number of defects reaching the customer"],answer:1,hint:"Which rating describes the effect if the failure did happen?",steps:[{title:"Key idea",body:"Severity describes how bad the effect would be; a device does not change that effect."},{title:"Apply",body:"Detection rating, RPN and escapes all fall; severity stays unless the design changes the effect."}],final:"Severity is unchanged → answer **B**",whyWrong:["Incorrect — a device that reliably catches the failure lowers the detection rating.","","Incorrect — the RPN is the product of the three ratings, so it falls when detection falls.","Incorrect — catching the defect at the step stops it moving on, so fewer reach the customer."],bookRef:"Book pp. 133, 522"},{id:"sv-5-648",phase:5,topic:"5.1.3",qtype:"scenario",difficulty:1,stem:"In a paint shop, the spray gun will not operate until the booth extraction fan has run for two minutes. Which poka-yoke setting method is this?",options:["Contact","Fixed-value","Motion-step","Visual control"],answer:2,hint:"Is the device checking a feature, a count or a sequence?",steps:[{title:"Key idea",body:"The fan step must happen **before** spraying can start: it enforces the order of steps."},{title:"Classify",body:"Order of steps = **motion-step** method."}],final:"Step order enforced → motion-step → answer **C**",whyWrong:["Incorrect — contact would sense a physical feature of the part, such as shape or position.","Incorrect — fixed-value would count a set number of items or actions.","","Incorrect — a visual control only shows status; this device blocks the step."],bookRef:"Syllabus 5.1.3"},{id:"sv-5-649",phase:5,topic:"5.1.3",qtype:"scenario",difficulty:1,stem:"A wheel-fixing station uses a torque tool linked to a controller. The fixture will not release the wheel until **five** bolts have been tightened to torque. Which setting method is this?",options:["Contact","Fixed-value","Motion-step","Source inspection"],answer:1,hint:"The device counts something.",steps:[{title:"Key idea",body:"The controller checks that a **set number** of actions (five tightenings) is complete."},{title:"Classify",body:"A count check is the **fixed-value** method."}],final:"Set number of actions → fixed-value → answer **B**",whyWrong:["Incorrect — contact would sense the shape or position of the wheel or bolts.","","Incorrect — motion-step would check that steps occur in a set order, not how many are done.","Incorrect — source inspection is Shingo's general idea of checking causes, not a setting method."],bookRef:"Syllabus 5.1.3"},{id:"sv-5-650",phase:5,topic:"5.1.3",qtype:"scenario",difficulty:2,stem:"Two SIM card types that look identical are stored in adjacent bins, and installers sometimes pick the wrong one. The FMEA shows this as the highest-risk failure mode. Which control is STRONGEST?",options:["Add a weekly audit of SIM types used on completed jobs","Chart the weekly wrong-SIM rate on a P chart","Redesign the kit so each job only issues the SIM type for that order","Retrain installers and add a reminder to the job sheet"],answer:2,hint:"Remove root cause > flag > inspect > train.",steps:[{title:"Key idea",body:"Controls that remove the error condition rank above monitoring, inspection and training (p. 557)."},{title:"Apply",body:"Issuing only the correct SIM makes the wrong pick impossible → prevention."}],final:"Make the wrong pick impossible → answer **C**",whyWrong:["Incorrect — an audit is Type 3 inspection; it finds wrong SIMs after the job is done.","Incorrect — SPC shows that the rate shifted but ranks below poka-yoke.","","Incorrect — training and SOP reminders are the weakest controls in the book's ranking."],bookRef:"Book pp. 522, 557"},{id:"sv-5-651",phase:5,topic:"5.1.3",qtype:"scenario",difficulty:2,stem:"A configuration change fails occasionally. A new script now **rolls the change back automatically** within a minute, so customers see only a brief drop. Which level of the mistake-proofing hierarchy is this?",options:["Detect","Eliminate","Facilitate","Mitigate"],answer:3,hint:"Does it stop the error, catch it, or reduce the impact?",steps:[{title:"Key idea",body:"Mitigation accepts that the failure got through and **reduces its impact**."},{title:"Apply",body:"Automatic rollback shortens the outage; it does not stop the failure → **mitigate**."}],final:"Reduces impact after failure → mitigate → answer **D**",whyWrong:["Incorrect — detect catches the error before it propagates; here the failure has already reached customers.","Incorrect — eliminate would remove the error-prone step; the failure can still occur here.","Incorrect — facilitate makes the correct action easier, such as a template or a drop-down.",""],bookRef:"Syllabus 5.1.3"},{id:"sv-5-652",phase:5,topic:"5.1.3",qtype:"scenario",difficulty:2,stem:"Engineers used to type router configurations by hand. Now an auto-provisioning template generates and pushes the configuration directly from the order. Which level of the mistake-proofing hierarchy is this?",options:["Detect","Facilitate","Mitigate","Replace"],answer:3,hint:"A more reliable process, often automation, takes the place of the manual one.",steps:[{title:"Key idea",body:"**Replace** substitutes a more reliable process, often automation, for the error-prone one."},{title:"Apply",body:"The template takes over the manual configuration step → replace."}],final:"Automation replaces manual entry → answer **D**",whyWrong:["Incorrect — detect catches an error after it is made; here the typing error cannot be made.","Incorrect — facilitate makes the manual action easier (e.g. drop-downs); here the manual typing is gone.","Incorrect — mitigate reduces the impact of an error that got through, such as an automatic rollback.",""],bookRef:"Syllabus 5.1.3"},{id:"sv-5-653",phase:5,topic:"5.1.3",qtype:"scenario",difficulty:2,stem:"The billing system **holds the bill run automatically** if the total charges differ from the previous cycle by more than a set percentage, and no bills are sent until the run is checked. Which corrective action type is this?",options:["Type 1 corrective action (countermeasure)","Type 3 corrective action (inspection)","Standard operating procedure","Type 2 corrective action (flag)"],answer:3,hint:"Is the error impossible, or detected and stopped?",steps:[{title:"Key idea",body:"A Type 2 flag **detects** that the error condition occurred and **shuts down** so the defect does not move on (p. 522)."},{title:"Apply",body:"Wrong charges can still occur, but the run is held → detection that stops the process."}],final:"Detects and holds the run → Type 2 → answer **D**",whyWrong:["Incorrect — Type 1 removes the error condition; here the wrong charges can still be calculated.","Incorrect — Type 3 is inspection or audit by people; this check is automatic and stops the process.","Incorrect — an SOP is a written instruction; it neither detects nor stops anything.",""],bookRef:"Book p. 522"},{id:"sv-5-654",phase:5,topic:"5.1.3",qtype:"best-action",difficulty:3,stem:"Welds sometimes crack because a fixture clamp is left loose. The team added a **second final inspector** at the end of the line instead of checking clamp pressure at the welding station. Was this an appropriate action?",options:["Yes, because two inspectors find more defects than one","Yes, because final inspection is the core of Shingo's approach","No, because checking the cause at the station would stop the cracked welds being made","No, because inspection can never be used in a control plan"],answer:2,hint:"Inspect the cause at the source, not the product at the end.",steps:[{title:"Key idea",body:"Source inspection checks the error condition (the loose clamp) at the moment it happens."},{title:"Apply",body:"A clamp-pressure check at the station stops the defect being made; a second final inspector does not."}],final:"Check the cause at source → answer **C**",whyWrong:["Incorrect — more inspection still finds defects only after they are made, and misses some.","Incorrect — Shingo moved from final (judgment) inspection to source inspection of the cause.","","Incorrect — inspection is allowed as short-term containment; it is just a weak permanent control."],bookRef:"Syllabus 5.1.3"},{id:"sv-5-655",phase:5,topic:"5.1.3",qtype:"best-action",difficulty:3,stem:"A detection device on a labelling line is found **switched off** on night shift. Operators say it stops the line for false alarms several times a shift. What is the BEST action?",options:["Find and fix the cause of the false alarms, then reinstate the device with periodic checks","Remove the device and rely on the end-of-shift label audit","Issue a written warning and retrain the night-shift operators","Add a second operator to inspect every label by eye"],answer:0,hint:"A bypassed device is a silent failure — why was it bypassed?",steps:[{title:"Key idea",body:"A poka-yoke only controls the process while it works; frequent false stops invite bypassing."},{title:"Apply",body:"Fix the device's reliability, put it back, and verify it periodically through the control plan."}],final:"Fix the false alarms and verify the device → answer **A**",whyWrong:["","Incorrect — falling back to an audit replaces poka-yoke with weaker Type 3 inspection.","Incorrect — blame and training ignore the real problem: the device is not working reliably.","Incorrect — visual 100% inspection is fatigue-prone containment, ranked below poka-yoke."],bookRef:"Book pp. 557–560"},{id:"sv-5-656",phase:5,topic:"5.1.3",qtype:"best-action",difficulty:3,stem:"After a prevention device made a 'wrong tariff code' failure mode almost impossible, the Green Belt **deleted** that line from the FMEA and from the control plan. Was this an appropriate action?",options:["Yes, because a prevention device removes the need for any further record","Yes, because only failure modes with a high occurrence belong in an FMEA","No, because the line should be re-rated and the device kept as a verified control","No, because a prevention device should raise the detection rating instead"],answer:2,hint:"What keeps a device working after the project ends?",steps:[{title:"Key idea",body:"The failure mode still exists; the device lowers its occurrence, and the RPN is recalculated."},{title:"Apply",body:"Keep the line, re-rate it, and list the device in the control plan with periodic verification."}],final:"Re-rate and keep the control recorded → answer **C**",whyWrong:["Incorrect — an unrecorded device can be removed or bypassed without anyone noticing.","Incorrect — the FMEA lists all failure modes; ratings show their risk.","","Incorrect — prevention lowers occurrence; it does not raise any rating."],bookRef:"Book pp. 133, 557–560"},{id:"sv-5-657",phase:5,topic:"5.1.3",qtype:"output",difficulty:2,stem:`The monthly poka-yoke verification log for an activation workflow is shown.

\`\`\`
Poka-yoke verification log – October
Device  Description                         Test method          Result
PY-01   Serial-number match before activate Inject wrong serial  Blocked
PY-02   Mandatory fields on order form      Submit blank field   Blocked
PY-03   Line-test interlock before handover Force failed test    Passed (bypass flag ON)
PY-04   Tariff drop-down from master data   Try invalid tariff   Not selectable
\`\`\`

Which conclusion is CORRECT?`,options:["All four devices are working as designed","PY-03 is not currently an effective control and needs action","PY-04 has failed because the invalid tariff could not be tested","PY-01 should be replaced by a weekly audit"],answer:1,hint:"A device is effective only if the deliberate error is stopped.",steps:[{title:"Read",body:"PY-01, 02 and 04 stopped the injected error. PY-03 'Passed' a forced failure with its bypass ON."},{title:"Decide",body:"A bypassed device is a silent failure: PY-03 needs the bypass removed and re-verification."}],final:"PY-03 is bypassed → answer **B**",whyWrong:["Incorrect — PY-03 let a failed test through because its bypass flag was on.","","Incorrect — 'Not selectable' is the correct result for a prevention device.","Incorrect — PY-01 blocked the wrong serial, so it works; an audit would be weaker."],bookRef:"Book pp. 557–560"},{id:"sv-5-658",phase:5,topic:"5.1.3",qtype:"output",difficulty:2,stem:`Three order-entry teams use different controls for the same keying error. One month of data:

\`\`\`
Team  Control used                        Errors made  Defects escaping
T1    Manual peer review                  305          61
T2    Validation that blocks submission   312           2
T3    Values pulled from the CRM record     0           0
\`\`\`

Which statement is CORRECT?`,options:["T2 uses prevention, because almost no defects escape","T1 uses detection poka-yoke, because errors are found","T3 uses prevention, because the error is no longer made","T2 and T3 use the same type of control"],answer:2,hint:"Look at 'Errors made', not only 'Defects escaping'.",steps:[{title:"Read",body:"T3: 0 errors made → the error is impossible. T2: errors still made but almost all caught. T1: errors made and many escape."},{title:"Classify",body:"T3 = prevention, T2 = detection, T1 = inspection."}],final:"Zero errors made → prevention → answer **C**",whyWrong:["Incorrect — T2 still makes over 300 errors; it catches them, which is detection.","Incorrect — peer review is human inspection (Type 3), not a poka-yoke device.","","Incorrect — T2 detects errors after they are made; T3 stops them being made."],bookRef:"Book p. 522"},{id:"sv-5-659",phase:5,topic:"5.1.3",qtype:"output",difficulty:3,stem:`A draft poka-yoke register is shown.

\`\`\`
Row  Device                                              Method       Function
1    Connector keyed so it fits one way only             Contact      Prevention
2    Form will not submit until all 9 fields are filled  Motion-step  Prevention
3    Counter beeps if fewer than 6 screws are driven     Fixed-value  Detection
4    Ticket cannot close before verification is logged   Motion-step  Prevention
\`\`\`

Which row is classified INCORRECTLY?`,options:["Row 1","Row 2","Row 3","Row 4"],answer:1,hint:"Check the Method column against feature / count / sequence.",steps:[{title:"Check",body:"Row 2 checks that a **set number** of fields is complete → fixed-value, not motion-step."},{title:"Confirm",body:"Rows 1, 3 and 4 match their method and function."}],final:"Nine mandatory fields is fixed-value → answer **B**",whyWrong:["Incorrect — a keyed shape is the contact method, and it makes the error impossible.","","Incorrect — a count of screws is fixed-value, and a beep after the event is detection.","Incorrect — enforcing verification before closure is the order of steps → motion-step."],bookRef:"Syllabus 5.1.3"},{id:"sv-5-660",phase:5,topic:"5.1.3",qtype:"output",difficulty:2,stem:`Two devices were trialled for four weeks each on the same missing-label error.

\`\`\`
Device trial – missing label
Device                       Errors sensed   Units stopped   Defects escaping
Warning light only           118             0               23
Line stop on sensor signal   121             121             0
\`\`\`

Which conclusion is CORRECT?`,options:["The warning light is a prevention device because it sensed the error","The line stop is weaker because it stopped more units than the light","Both devices performed equally because they sensed similar numbers of errors","Both devices sensed the error; only the control function stopped defects moving on"],answer:3,hint:"Same sensing, different regulatory function.",steps:[{title:"Read",body:"Errors sensed are similar (118 vs 121). The light stopped nothing and 23 defects escaped; the stop halted all 121 and none escaped."},{title:"Decide",body:"A warning relies on people reacting; the control (shut-down) function stops the defect moving forward."}],final:"Shut-down beats warning → answer **D**",whyWrong:["Incorrect — sensing an error after it occurs is detection; prevention makes the error impossible.","Incorrect — stopping every affected unit is exactly why a shut-down beats a warning.","Incorrect — sensing is similar, but 23 defects escaped with the light and none with the stop.",""],bookRef:"Book p. 522"},{id:"sv-5-661",phase:5,topic:"5.1.3",qtype:"true-false",difficulty:1,stem:"In Shingo's approach, the aim of poka-yoke is to stop errors turning into defects, rather than to find defects after they are made. True or False?",options:["True","False"],answer:0,hint:"Inspection versus source control.",steps:[{title:"Key idea",body:"Poka-yoke breaks the link between error and defect, at the moment the error happens."},{title:"Decide",body:"The statement describes that aim correctly."}],final:"The statement is true → answer **True**",whyWrong:["","Incorrect — finding defects after they are made is inspection; poka-yoke works at the source."],bookRef:"Syllabus 5.1.3"},{id:"sv-5-662",phase:5,topic:"5.1.3",qtype:"sequence",difficulty:2,stem:`Put the levels of the mistake-proofing hierarchy in order, from MOST to least preferred.

- **P** — Detect
- **Q** — Eliminate
- **R** — Facilitate
- **S** — Mitigate`,options:["Q → R → P → S","R → Q → P → S","Q → P → R → S","Q → R → S → P"],answer:0,hint:"Start by removing the step; end by limiting the damage.",steps:[{title:"Key idea",body:"Eliminate (and replace) → facilitate → detect → mitigate."},{title:"Apply",body:"Q → R → P → S."}],final:"Eliminate, facilitate, detect, mitigate → answer **A**",whyWrong:["","Incorrect — eliminating the step outranks making the right action easier.","Incorrect — facilitating (making errors less likely) outranks detecting errors that occur.","Incorrect — mitigation is the last resort, after detection."],bookRef:"Syllabus 5.1.3"},{id:"sv-5-663",phase:5,topic:"5.1.3",qtype:"sequence",difficulty:3,stem:`Put these steps for choosing a mistake-proofing control in the correct order.

- **P** — If the error cannot be designed out, detect it at once and stop the process
- **Q** — Use the FMEA to find the failure modes with the highest risk
- **R** — Record the device in the control plan and test it on purpose
- **S** — Ask whether the error condition can be removed by design`,options:["S → Q → P → R","Q → S → P → R","Q → P → S → R","Q → S → R → P"],answer:1,hint:"Find the risk → try prevention → fall back to detection → record and verify.",steps:[{title:"Key idea",body:"Highest-risk failure modes first, then Type 1 prevention, then Type 2 detection, then control plan and verification."},{title:"Apply",body:"Q → S → P → R."}],final:"FMEA, design out, detect, record → answer **B**",whyWrong:["Incorrect — the team first needs the FMEA to know where to act.","","Incorrect — design removal (Type 1) is considered before detection (Type 2).","Incorrect — recording and verifying the device comes after it has been chosen."],bookRef:"Book pp. 522, 557–560"},{id:"sv-5-664",phase:5,topic:"5.2.1",qtype:"concept",difficulty:1,stem:"A machine drills 30 holes a minute. According to the book, which is a good rational subgroup for an Xbar-R chart?",options:["Four holes, one taken every 15 minutes","Four holes, one from each of four drills","Four holes drilled consecutively","Thirty holes averaged into one value"],answer:2,hint:"Same conditions, short time.",steps:[{title:"Key idea",body:"A rational subgroup holds conditions constant: consecutive units, same machine, set-up and material."},{title:"Apply",body:"The book's example is four consecutively drilled holes."}],final:"Consecutive units → rational → answer **C**",whyWrong:["Incorrect — spreading the units over an hour lets conditions change inside the subgroup.","Incorrect — units from different machines mix streams; that is not a rational subgroup.","","Incorrect — averaging a minute's output into one value loses the within-subgroup spread."],bookRef:"Book pp. 517–519"},{id:"sv-5-665",phase:5,topic:"5.2.1",qtype:"concept",difficulty:1,stem:"Why should a subgroup be taken from units in **production order** rather than picked from a pile of finished units?",options:["Units from a pile are easier to measure, which reduces measurement error","Units from a pile always give narrower control limits","Production order is needed only for attribute charts","Consecutive units share the same conditions, so only common cause sits inside the subgroup"],answer:3,hint:"A rational subgroup = similar conditions in a short time.",steps:[{title:"Key idea",body:"Consecutive units are made under the same set-up, material and operator in a short time."},{title:"Apply",body:"A pile mixes units from different times and conditions, so causes end up inside the subgroup."}],final:"Consecutive units keep conditions constant → answer **D**",whyWrong:["Incorrect — ease of measuring is not the point; the pile hides when and how each unit was made.","Incorrect — units of unknown origin mix conditions, which tends to widen the limits.","Incorrect — time order matters for every control chart, variables and attribute alike.",""],bookRef:"Book pp. 517–519"},{id:"sv-5-666",phase:5,topic:"5.2.1",qtype:"concept",difficulty:2,stem:"On an Xbar-R chart, which variation sets the **width** of the control limits?",options:["The variation within the subgroups","The variation between the subgroup means","The variation between the specification limits","The variation in the number of subgroups"],answer:0,hint:"R-bar comes from inside each subgroup.",steps:[{title:"Key idea",body:"The limits are built from R-bar, the average range **inside** the subgroups."},{title:"Apply",body:"So within-subgroup variation sets the width; it must contain common cause only."}],final:"Within-subgroup variation sets the width → answer **A**",whyWrong:["","Incorrect — between-subgroup variation is what the chart tests against the limits.","Incorrect — specification limits are not part of a control chart.","Incorrect — the number of subgroups affects how reliable the limits are, not what sets their width."],bookRef:"Book pp. 517–519"},{id:"sv-5-667",phase:5,topic:"5.2.1",qtype:"concept",difficulty:1,stem:"According to the book, what is the most common error made with Xbar-R charts?",options:["Too few decimal places","Wrong subgrouping","Using too many tests","Plotting the range first"],answer:1,hint:"The chart is only as good as the subgroups behind it.",steps:[{title:"Key idea",body:"The book stresses that Xbar-R is frequently done incorrectly, mostly through **wrong subgrouping**."},{title:"Apply",body:"Mixed sources inside subgroups widen the limits and hide special causes."}],final:"Wrong subgrouping → answer **B**",whyWrong:["Incorrect — rounding is a minor issue; the book singles out how subgroups are formed.","","Incorrect — the number of tests switched on is not the error the book highlights.","Incorrect — the range chart should be read first; that is correct practice, not an error."],bookRef:"Book pp. 517–519"},{id:"sv-5-668",phase:5,topic:"5.2.1",qtype:"concept",difficulty:2,stem:"In a stable process sampled correctly, how should the team respond to common-cause variation?",options:["Adjust the process after every point above the mean","Investigate each point for an assignable cause","Leave the process alone and do not adjust it","Recalculate the limits each time a point moves"],answer:2,hint:"Common cause = the system's normal random scatter.",steps:[{title:"Key idea",body:"In a stable process the points scatter randomly around the average with no trends or shifts."},{title:"Apply",body:"The book says you should **not adjust** for common-cause variation; only special causes need action."}],final:"Do not adjust for common cause → answer **C**",whyWrong:["Incorrect — adjusting for common cause is tampering and adds variation.","Incorrect — investigation is for special causes; common cause is the system's normal noise.","","Incorrect — limits are frozen; they are recalculated only after a verified change."],bookRef:"Book pp. 517–519"},{id:"sv-5-669",phase:5,topic:"5.2.1",qtype:"concept",difficulty:2,stem:"What is the drawback of choosing a very large subgroup?",options:["They make the Xbar chart less sensitive to shifts in the mean","They cannot be used with an Xbar chart at all","They make the control limits wider than the specification limits","They cost more to measure and are more likely to span a change in conditions"],answer:3,hint:"What is the price of a bigger subgroup?",steps:[{title:"Key idea",body:"Bigger n narrows the Xbar limits, but each subgroup takes more effort and longer to collect."},{title:"Apply",body:"A longer collection window risks mixing conditions inside the subgroup."}],final:"Cost and risk of spanning a change → answer **D**",whyWrong:["Incorrect — larger subgroups make the Xbar chart more sensitive, not less.","Incorrect — large subgroups are charted on Xbar-S, which still uses an Xbar chart.","Incorrect — control limits are not compared with specification limits on the chart.",""],bookRef:"Book pp. 517–519"},{id:"sv-5-670",phase:5,topic:"5.2.1",qtype:"concept",difficulty:1,stem:"What is the FIRST question in the book's control-chart selection tree?",options:["What type of data is being collected?","How large is each subgroup?","Is the sample size constant or variable?","How wide are the specification limits?"],answer:0,hint:"The tree branches on data first.",steps:[{title:"Key idea",body:"The selection tree starts with the **type of data** (continuous or attribute)."},{title:"Apply",body:"Only then does it ask about subgroup size or about defects, defectives and sample size."}],final:"Data type comes first → answer **A**",whyWrong:["","Incorrect — subgroup size is the second question, for continuous data only.","Incorrect — constant or variable n is asked later, for attribute data.","Incorrect — specification limits play no part in choosing a control chart."],bookRef:"Book p. 530"},{id:"sv-5-671",phase:5,topic:"5.2.1",qtype:"concept",difficulty:1,stem:"Which chart does the book recommend for continuous data collected in subgroups of **10 or more**?",options:["I-MR chart","U chart","Xbar-R chart","Xbar-S chart"],answer:3,hint:"Large subgroups: the range wastes information.",steps:[{title:"Key idea",body:"Book table: 1 → I-MR, 2–5 → Xbar-R, 10 or more → Xbar-S."},{title:"Apply",body:"Subgroups of 10+ → Xbar-S."}],final:"n ≥ 10 → Xbar-S → answer **D**",whyWrong:["Incorrect — I-MR is for subgroups of one.","Incorrect — a U chart is for defects (attribute data), not continuous measurements.","Incorrect — Xbar-R is the book's choice for subgroups of 2 to 5.",""],bookRef:"Book p. 530"},{id:"sv-5-672",phase:5,topic:"5.2.1",qtype:"concept",difficulty:1,stem:"In the book's chart-selection tree, when are CuSum or EWMA charts chosen?",options:["When the subgroup size is exactly one","When small, sustained shifts must be detected","When the data are counts of defectives","When the sample size varies between subgroups"],answer:1,hint:"Special cases beyond the Shewhart charts.",steps:[{title:"Key idea",body:"CuSum and EWMA are listed as special cases for **small shifts** that Shewhart charts may miss."},{title:"Eliminate",body:"Subgroup size, defectives and variable n are handled inside the standard tree."}],final:"Small sustained shifts → answer **B**",whyWrong:["Incorrect — a subgroup of one leads to an I-MR chart.","","Incorrect — defectives lead to NP or P charts.","Incorrect — a varying sample size changes NP to P, or C to U."],bookRef:"Book p. 530"},{id:"sv-5-673",phase:5,topic:"5.2.1",qtype:"concept",difficulty:2,stem:"A continuous characteristic is charted on an Xbar-R chart with subgroups of 4. The team now plans to measure **12** units per subgroup. What change of chart does the book's selection tree suggest?",options:["Move from Xbar-R to I-MR","Move from Xbar-R to a P chart","Move from Xbar-R to Xbar-S","Keep Xbar-R, because subgroup size does not matter"],answer:2,hint:"2–5 → Xbar-R; 10 or more → Xbar-S.",steps:[{title:"Key idea",body:"For continuous data the tree branches on subgroup size: 1 → I-MR, 2–5 → Xbar-R, 10+ → Xbar-S."},{title:"Apply",body:"A rise to 12 per subgroup moves the choice to Xbar-S, which uses all the data rather than only the extremes."}],final:"n = 12 → Xbar-S → answer **C**",whyWrong:["Incorrect — I-MR is for subgroups of one, not larger subgroups.","Incorrect — the data are still continuous; a P chart is for proportions defective.","","Incorrect — subgroup size is the second branch of the tree for continuous data."],bookRef:"Book p. 530"},{id:"sv-5-674",phase:5,topic:"5.2.1",qtype:"concept",difficulty:2,stem:"How does the book advise the sampling rate should change when a new control chart is started?",options:["Start with few samples, then increase once the first signal appears","Keep the same rate permanently once it has been agreed","Sample only when the operator suspects a problem","Take extra samples at first, then reduce once the process stays in control"],answer:3,hint:"Learn the process quickly, then relax.",steps:[{title:"Key idea",body:"At the start, take **extra samples**; reduce the rate once the process stays in control."},{title:"Eliminate",body:"Late, fixed or suspicion-based sampling all conflict with this guidance."}],final:"Start high, then reduce → answer **D**",whyWrong:["Incorrect — waiting for a signal before sampling more risks missing early shifts.","Incorrect — the book allows reducing the rate once the process shows it stays in control.","Incorrect — sampling on suspicion is biased and misses shifts nobody noticed.",""],bookRef:"Book p. 529"},{id:"sv-5-675",phase:5,topic:"5.2.1",qtype:"concept",difficulty:1,stem:"What does a **C chart** plot?",options:["The number of defects found in a sample of constant size","The number of defective units in a sample of constant size","The proportion of defective units in samples of varying size","The number of defects per unit in samples of varying size"],answer:0,hint:"C = count of defects, constant n.",steps:[{title:"Key idea",body:"Defects (a unit can have several) with a **constant** sample size → C chart."},{title:"Eliminate",body:"NP and P count defectives; U allows a varying sample size."}],final:"C = defects, constant n → answer **A**",whyWrong:["","Incorrect — the number of defective units with constant n is the NP chart.","Incorrect — the proportion defective with varying n is the P chart.","Incorrect — defects per unit with varying n is the U chart."],bookRef:"Book p. 530"},{id:"sv-5-676",phase:5,topic:"5.2.1",qtype:"concept",difficulty:2,stem:"Why is an Xbar-R chart usually preferred to an I-MR chart when rational subgroups of four or five are available?",options:["The I-MR chart cannot detect points beyond 3σ","The Xbar chart is more sensitive to shifts in the process mean","The Xbar chart does not need the data in time order","The I-MR chart is only used for attribute data"],answer:1,hint:"Averages vary less than individual values.",steps:[{title:"Key idea",body:"The book notes that the I-MR chart is **less sensitive** than the Xbar chart."},{title:"Apply",body:"Subgroup means have less spread, so the limits are tighter and shifts show sooner."}],final:"Xbar is more sensitive → answer **B**",whyWrong:["Incorrect — the I chart uses Test 1 for points beyond 3σ like any Shewhart chart.","","Incorrect — every control chart needs data in time order.","Incorrect — I-MR is a variables chart for continuous data with subgroups of one."],bookRef:"Book pp. 518, 530"},{id:"sv-5-677",phase:5,topic:"5.2.1",qtype:"concept",difficulty:1,stem:"In SPC data collection, what is meant by the **population**?",options:["The units actually measured for the chart","The units that fall outside the control limits","Everything the process has made or will make","The subgroups used to calculate the limits"],answer:2,hint:"Population vs sample.",steps:[{title:"Key idea",body:"The book defines the population as everything made or to be made, and the sample as the items measured."},{title:"Apply",body:"The sample must represent the population, which is why bias must be avoided."}],final:"Population = all output, past and future → answer **C**",whyWrong:["Incorrect — the units actually measured are the sample.","Incorrect — out-of-limit units are signals, not the population.","","Incorrect — the subgroups are samples taken from the population."],bookRef:"Book pp. 517–519"},{id:"sv-5-678",phase:5,topic:"5.2.1",qtype:"concept",difficulty:3,stem:"Each hourly subgroup is five consecutive calls handled by **one** agent, and a different agent is sampled each hour. If agents differ in handle time, how will the Xbar chart show those differences?",options:["As within-subgroup variation that widens the limits","As measurement-system variation in the range chart","It will not show them, because all calls are consecutive","As between-subgroup variation that can appear as signals"],answer:3,hint:"Where does the agent change happen — inside or between subgroups?",steps:[{title:"Key idea",body:"Whatever changes **between** subgroups is tested against the limits; whatever changes **inside** them widens the limits."},{title:"Apply",body:"The agent changes between subgroups, so agent differences appear as between-subgroup variation and can signal."}],final:"Agent differences fall between subgroups → answer **D**",whyWrong:["Incorrect — each subgroup holds one agent, so agent differences are not inside the subgroups.","Incorrect — differences between agents are process variation, not gauge variation.","Incorrect — consecutive calls within an agent still differ from the next agent's calls.",""],bookRef:"Book pp. 517–519"},{id:"sv-5-679",phase:5,topic:"5.2.1",qtype:"concept",difficulty:1,stem:"Which chart plots the **number of defective units** when every sample is the same size?",options:["C chart","NP chart","P chart","U chart"],answer:1,hint:"Defectives + constant n.",steps:[{title:"Key idea",body:"Defectives (whole units that fail) with a **constant** sample size → NP chart."},{title:"Eliminate",body:"C and U count defects; P is the proportion form for variable n."}],final:"Defectives, constant n → NP → answer **B**",whyWrong:["Incorrect — the C chart counts defects (flaws), not defective units.","","Incorrect — the P chart plots the proportion defective and is needed when n varies.","Incorrect — the U chart plots defects per unit with a varying sample size."],bookRef:"Book p. 530"},{id:"sv-5-680",phase:5,topic:"5.2.1",qtype:"concept",difficulty:2,stem:"For attribute data, which two questions does the book's chart-selection table ask?",options:["Defects or defectives, and is the sample size constant","Normal or non-normal, and is the variance constant","Short-term or long-term, and is the process capable","Inputs or outputs, and is the mean on target"],answer:0,hint:"C, U, NP, P — what separates them?",steps:[{title:"Key idea",body:"Defects → C or U; defectives → NP or P."},{title:"Apply",body:"Then constant sample size → C or NP; variable → U or P."}],final:"Defects/defectives and constant/variable n → answer **A**",whyWrong:["","Incorrect — normality and equal variance are hypothesis-test checks, not chart-selection questions.","Incorrect — capability is a separate study; the chart does not depend on it.","Incorrect — X versus Y decides SPC versus SPM, not which attribute chart to use."],bookRef:"Book p. 530"},{id:"sv-5-681",phase:5,topic:"5.2.1",qtype:"concept",difficulty:1,stem:"Which chart plots the **number of defects per unit** when the sample size varies?",options:["C chart","NP chart","P chart","U chart"],answer:3,hint:"Defects + variable n.",steps:[{title:"Key idea",body:"Defects (a unit can have several) with a variable sample size → **U** chart."},{title:"Eliminate",body:"C = defects, constant n; NP and P count defectives."}],final:"Defects per unit, variable n → U → answer **D**",whyWrong:["Incorrect — the C chart counts defects with a constant sample size.","Incorrect — the NP chart counts defective units with a constant sample size.","Incorrect — the P chart plots the proportion of defective units.",""],bookRef:"Book p. 530"},{id:"sv-5-682",phase:5,topic:"5.2.1",qtype:"concept",difficulty:2,stem:"On an I-MR chart, what plays the part that R-bar plays on an Xbar-R chart?",options:["The range inside each subgroup of five","The average moving range between consecutive values","The standard deviation of each subgroup","The distance between the specification limits"],answer:1,hint:"With n = 1 there is no spread inside a subgroup.",steps:[{title:"Key idea",body:"With a subgroup of one, short-term variation is estimated from consecutive points."},{title:"Apply",body:"The average **moving range** sets the width of the I-MR limits."}],final:"Average moving range → answer **B**",whyWrong:["Incorrect — an I-MR chart has subgroups of one, so there is no range inside a subgroup.","","Incorrect — subgroup standard deviations belong to the Xbar-S chart.","Incorrect — specification limits are never used to set control limits."],bookRef:"Book pp. 530–531"},{id:"sv-5-683",phase:5,topic:"5.2.1",qtype:"concept",difficulty:3,stem:"What is the purpose of the cookbook step 'set the basis for subgrouping'?",options:["To decide how many control-chart tests to switch on","To decide which specification limits to draw on the chart","To decide which variation is kept inside subgroups and which falls between them","To decide who will be trained to read the chart"],answer:2,hint:"Subgrouping decides where each source of variation goes.",steps:[{title:"Key idea",body:"The basis for subgrouping keeps only common cause **inside** subgroups."},{title:"Apply",body:"Known sources such as shift or lot should change **between** subgroups so they can be seen."}],final:"Decide inside vs between → answer **C**",whyWrong:["Incorrect — test selection is part of interpreting the chart, not the subgrouping basis.","Incorrect — specification limits are never drawn on a control chart.","","Incorrect — training is the last cookbook step and is separate from subgrouping."],bookRef:"Book p. 525"},{id:"sv-5-684",phase:5,topic:"5.2.1",qtype:"concept",difficulty:2,stem:"Which statement about mixing several machines inside each subgroup is CORRECT?",options:["It makes the Xbar chart more sensitive because more sources are represented","It is the book's recommended way to make subgroups represent the process","It has no effect, because the limits are set by the number of subgroups","It inflates R-bar, so the limits widen and machine differences are hidden"],answer:3,hint:"What happens to the range inside each subgroup?",steps:[{title:"Key idea",body:"Machine-to-machine differences inside subgroups enlarge every range, so R-bar and the limits grow."},{title:"Apply",body:"The cause you wanted to detect is now buried inside the subgroups."}],final:"Inflated R-bar hides the cause → answer **D**",whyWrong:["Incorrect — mixing sources makes the chart less sensitive, not more.","Incorrect — the book says items from different machines are not a rational subgroup.","Incorrect — the width of the limits comes from within-subgroup variation, not the number of subgroups.",""],bookRef:"Book pp. 517–519"},{id:"sv-5-685",phase:5,topic:"5.2.1",qtype:"concept",difficulty:3,stem:"Which statement about attribute charts is CORRECT?",options:["A P chart can do everything an NP chart can","An NP chart can be used when the sample size varies","A C chart plots the proportion of defective units","A U chart counts whole units that fail"],answer:0,hint:"P works for constant and variable n.",steps:[{title:"Key idea",body:"The book notes that a P chart can do everything an NP chart can (likewise U for C)."},{title:"Eliminate",body:"Each wrong option swaps defects/defectives or constant/variable n."}],final:"P can do everything NP can → answer **A**",whyWrong:["","Incorrect — the NP chart needs a constant sample size; a varying n calls for a P chart.","Incorrect — a C chart counts defects; the proportion defective is the P chart.","Incorrect — whole units that fail are defectives (NP or P); a U chart plots defects per unit."],bookRef:"Book pp. 521, 530"},{id:"sv-5-686",phase:5,topic:"5.2.1",qtype:"concept",difficulty:3,stem:"Which statement about the C and U charts is CORRECT?",options:["A C chart is the correct choice when the sample size varies from day to day","A U chart can be used wherever a C chart can, because it also handles a varying sample size","A U chart plots the proportion of units that are defective","A C chart counts the number of whole units that fail inspection"],answer:1,hint:"U is the 'per unit' form of C.",steps:[{title:"Key idea",body:"The book notes that U can do everything C can (as P can for NP)."},{title:"Eliminate",body:"Each wrong option swaps constant/variable n or defects/defectives."}],final:"U can do everything C can → answer **B**",whyWrong:["Incorrect — a varying sample size calls for the U chart; the C chart needs a constant n.","","Incorrect — the proportion defective is the P chart; U plots defects per unit.","Incorrect — whole units that fail are defectives (NP chart); C counts defects."],bookRef:"Book pp. 520, 530"},{id:"sv-5-687",phase:5,topic:"5.2.1",qtype:"concept",difficulty:3,stem:"Which statement about choosing a control chart is CORRECT?",options:["The choice depends on which chart the process owner is used to reading","The choice depends on how close the process is to the specification limits","The choice depends on the data type, subgroup size and constant or variable sample size","The choice depends on whether the process has already been shown to be capable"],answer:2,hint:"What does the selection tree branch on?",steps:[{title:"Key idea",body:"The tree branches on data type, then subgroup size (continuous) or defects/defectives and constant/variable n (attribute)."},{title:"Eliminate",body:"Preference, specs and capability are not branches of the tree."}],final:"The data decide the chart → answer **C**",whyWrong:["Incorrect — preference is not a criterion; the data decide the chart.","Incorrect — specifications play no part in control-chart selection.","","Incorrect — capability is a separate study; charts are chosen before stability is even known."],bookRef:"Book p. 530"},{id:"sv-5-688",phase:5,topic:"5.2.1",qtype:"concept",difficulty:2,stem:"Which statement about attribute and variables control charts is CORRECT?",options:["Variables charts usually need at least 50 units in each subgroup","Attribute data carry more information per unit than variables data","Both types of chart use the same subgroup sizes of 3 to 5","Attribute charts usually need much larger samples than variables charts"],answer:3,hint:"A good/bad result says less than a measurement.",steps:[{title:"Key idea",body:"Each attribute result is only good/bad or a count, so many units are needed to see a change."},{title:"Apply",body:"Variables subgroups are typically 3–5; P and NP samples usually exceed about 50."}],final:"Attribute charts need larger samples → answer **D**",whyWrong:["Incorrect — variables subgroups are typically small, about 3 to 5 units.","Incorrect — continuous (variables) data carry more information; that is why the book prefers them.","Incorrect — P and NP charts usually need samples above about 50, far more than 3 to 5.",""],bookRef:"Book pp. 517–519, 530"},{id:"sv-5-689",phase:5,topic:"5.2.1",qtype:"concept",difficulty:2,stem:"Which statement about the data used to set control limits is CORRECT?",options:["Limits come from past process data and are then frozen for new points","Limits come from the customer's specification and target values","Limits are recalculated each time a new point is plotted","Limits come from the best five subgroups collected in the study"],answer:0,hint:"Voice of the process, not voice of the customer.",steps:[{title:"Key idea",body:"Limits are calculated from past data collected while the process ran normally."},{title:"Apply",body:"Once set, they are frozen and new points are plotted against them."}],final:"Past data, then frozen → answer **A**",whyWrong:["","Incorrect — specifications never set control limits; limits are the voice of the process.","Incorrect — recalculating with every point lets a drifting process drag its own limits along.","Incorrect — choosing only the best subgroups biases the limits and makes them too narrow."],bookRef:"Book p. 525"},{id:"sv-5-690",phase:5,topic:"5.2.1",qtype:"statements",difficulty:2,stem:`Which statements about rational subgroups are CORRECT?

1. A subgroup should contain one unit from each machine so it represents the whole process.
2. Units in a subgroup should be made close together in time under the same conditions.
3. A known source such as a shift change should fall between subgroups, not inside them.
4. Subgroups should be as large as possible so that the limits are as narrow as possible.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Same conditions, short time; known sources between subgroups.",steps:[{title:"Check each",body:"1 false (mixes streams). 2 true. 3 true. 4 false (size is a trade-off; typically 3–5)."},{title:"Select",body:"The true pair is 2 and 3."}],final:"Statements 2 and 3 → answer **B**",whyWrong:["Incorrect — statement 1 is false: units from different machines are not a rational subgroup.","","Incorrect — statement 4 is false: large subgroups cost more and may span a change in conditions.","Incorrect — statements 1 and 4 are the two false statements."],bookRef:"Book pp. 517–519"},{id:"sv-5-691",phase:5,topic:"5.2.1",qtype:"statements",difficulty:2,stem:`Which statements about the I-MR and Xbar-R charts are CORRECT?

1. An I-MR chart needs subgroups of at least two units.
2. An Xbar-R chart suits a batch process with one result per batch.
3. The I-MR chart is less sensitive to a shift in the mean than the Xbar chart.
4. The I-MR chart estimates short-term variation from moving ranges.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"I-MR = subgroups of one, moving ranges, less sensitive.",steps:[{title:"Check each",body:"1 false (n = 1). 2 false (one result per batch → I-MR). 3 true. 4 true."},{title:"Select",body:"The true pair is 3 and 4."}],final:"Statements 3 and 4 → answer **C**",whyWrong:["Incorrect — statements 1 and 2 are both false.","Incorrect — statement 2 is false: one result per batch gives a subgroup of one → I-MR.","","Incorrect — statement 1 is false: an I-MR chart uses subgroups of one."],bookRef:"Book pp. 518, 530–531"},{id:"sv-5-692",phase:5,topic:"5.2.1",qtype:"statements",difficulty:2,stem:`Which statements about chart selection are CORRECT?

1. Defectives with a variable sample size are charted on a P chart.
2. Defects with a constant sample size are charted on an NP chart.
3. Continuous data with subgroups of one are charted on an Xbar-R chart.
4. Continuous data with subgroups of 10 or more are charted on an Xbar-S chart.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Defectives → NP/P; defects → C/U; n = 1 → I-MR; n ≥ 10 → Xbar-S.",steps:[{title:"Check each",body:"1 true. 2 false (C chart). 3 false (I-MR). 4 true."},{title:"Select",body:"The true pair is 1 and 4."}],final:"Statements 1 and 4 → answer **D**",whyWrong:["Incorrect — statement 2 is false: defects with constant n go on a C chart.","Incorrect — statements 2 and 3 are the two false statements.","Incorrect — statement 3 is false: subgroups of one go on an I-MR chart.",""],bookRef:"Book p. 530"},{id:"sv-5-693",phase:5,topic:"5.2.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A [?] subgroup is a small sample of units made under very similar conditions over a short period of time.`,options:["control","random","rational","stratified"],answer:2,hint:"The term the book uses for subgroups that hold conditions constant.",steps:[{title:"Key idea",body:"A **rational** subgroup keeps only common-cause variation inside it."},{title:"Eliminate",body:"Control, random and stratified are related SPC words with other meanings."}],final:"Rational subgroup → answer **C**",whyWrong:["Incorrect — 'control' describes the chart and its limits, not the way units are grouped.","Incorrect — a random sample spread over time can mix conditions; rational subgroups are consecutive units.","","Incorrect — stratified describes splitting data by a factor, not forming a subgroup."],bookRef:"Book pp. 517–519"},{id:"sv-5-694",phase:5,topic:"5.2.1",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

On an Xbar chart, the variation [?] subgroups is what is compared with the control limits to reveal special causes.`,options:["between","beyond","within","without"],answer:0,hint:"Within sets the limits; what do the limits test?",steps:[{title:"Key idea",body:"Within-subgroup variation sets the limits; **between**-subgroup variation is tested against them."},{title:"Apply",body:"Special causes should show up between subgroups."}],final:"Between-subgroup variation → answer **A**",whyWrong:["","Incorrect — 'beyond' describes points outside the limits, not a source of variation.","Incorrect — within-subgroup variation sets the width of the limits; it is not what they test.","Incorrect — 'without' does not describe any source of variation on the chart."],bookRef:"Book pp. 517–519"},{id:"sv-5-695",phase:5,topic:"5.2.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing words in the following sentence.

For attribute data, the chart depends on whether defects or defectives are counted and on whether the [?] is constant.`,options:["centre line","sample size","specification","target value"],answer:1,hint:"C vs U and NP vs P.",steps:[{title:"Key idea",body:"Constant sample size → C or NP; variable sample size → U or P."},{title:"Apply",body:"The missing words are 'sample size'."}],final:"Constant or variable sample size → answer **B**",whyWrong:["Incorrect — the centre line is calculated from the data; it does not choose the chart.","","Incorrect — specifications play no part in choosing a control chart.","Incorrect — a target value is not a branch in the chart-selection table."],bookRef:"Book p. 530"},{id:"sv-5-696",phase:5,topic:"5.2.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A [?] is a whole unit that fails the acceptance criteria, whatever the number of flaws it contains.`,options:["defect","defective","nonconformity","opportunity"],answer:1,hint:"Whole unit vs single flaw.",steps:[{title:"Key idea",body:"A **defective** is a whole unit that fails; a **defect** is one failed criterion."},{title:"Apply",body:"Defectives are charted on NP or P charts; defects on C or U charts."}],final:"Whole failed unit = defective → answer **B**",whyWrong:["Incorrect — a defect is one failed criterion; a unit can carry several defects.","","Incorrect — a nonconformity is another name for a single defect, not for the whole unit.","Incorrect — an opportunity is a chance for a defect to occur, not a failed unit."],bookRef:"Book p. 530"},{id:"sv-5-697",phase:5,topic:"5.2.1",qtype:"not-except",difficulty:1,stem:"Which is NOT a valid basis for choosing a control chart?",options:["Whether the data are continuous or attribute","The chart the manager prefers to read","The size of each subgroup","Whether the sample size is constant or variable"],answer:1,hint:"The data decide the chart.",steps:[{title:"Key idea",body:"Chart choice follows the data: type, subgroup size, defects/defectives and constant/variable n."},{title:"Apply",body:"Personal preference is not part of the selection tree."}],final:"Preference is not a basis → answer **B**",whyWrong:["Incorrect — data type is the first branch of the selection tree.","","Incorrect — subgroup size decides between I-MR, Xbar-R and Xbar-S.","Incorrect — constant or variable n decides between NP/P and C/U."],bookRef:"Book p. 530"},{id:"sv-5-698",phase:5,topic:"5.2.1",qtype:"not-except",difficulty:2,stem:"Which situation does NOT usually lead to a subgroup size of one?",options:["Low production volume","Destructive or costly testing","A high-volume line producing 30 units a minute","A batch process with one result per batch"],answer:2,hint:"When is it hard to get several units made under the same conditions?",steps:[{title:"Key idea",body:"Subgroups of one suit low volume, destructive or costly tests and batches (I-MR)."},{title:"Apply",body:"A fast line easily supplies consecutive units, so rational subgroups of 4–5 are practical."}],final:"High volume allows real subgroups → answer **C**",whyWrong:["Incorrect — low volume is a book reason for subgroups of one (I-MR).","Incorrect — destructive or costly tests are a book reason for subgroups of one.","","Incorrect — one result per batch gives a natural subgroup of one."],bookRef:"Book pp. 530–531"},{id:"sv-5-699",phase:5,topic:"5.2.1",qtype:"not-except",difficulty:1,stem:"Which KPI would NOT be charted on an attribute control chart?",options:["Number of errors found per invoice batch","Number of failed activations per day","Proportion of deliveries that arrive late","Average call-handling time in seconds"],answer:3,hint:"Counts and classifications vs measurements.",steps:[{title:"Key idea",body:"Attribute charts (C, U, NP, P) are for counts and classifications."},{title:"Apply",body:"Handle time is a continuous measurement → I-MR, Xbar-R or Xbar-S."}],final:"Time is continuous data → answer **D**",whyWrong:["Incorrect — errors per batch are defects, charted on a C or U chart.","Incorrect — failed activations are defectives, charted on an NP or P chart.","Incorrect — a proportion of late deliveries is defectives, charted on a P chart.",""],bookRef:"Book p. 530"},{id:"sv-5-700",phase:5,topic:"5.2.1",qtype:"not-except",difficulty:3,stem:"A team counts **defective** units each day. Which chart would NOT be suitable?",options:["C chart with a constant sample size","NP chart with a constant sample size","P chart with a variable sample size","P chart with a constant sample size"],answer:0,hint:"Defectives vs defects.",steps:[{title:"Key idea",body:"Defectives → NP or P; a P chart also covers constant n."},{title:"Apply",body:"A C chart counts defects (flaws), not defective units."}],final:"C charts count defects → answer **A**",whyWrong:["","Incorrect — NP with constant n is the standard chart for counts of defectives.","Incorrect — P with variable n is the standard chart for proportions defective.","Incorrect — a P chart can do everything an NP chart can, so it also works with constant n."],bookRef:"Book pp. 521, 530"},{id:"sv-5-701",phase:5,topic:"5.2.1",qtype:"not-except",difficulty:2,stem:"Which is NOT one of the decisions a team makes when setting up data collection for an Xbar-R chart?",options:["The subgroup size","Which specification limits to draw on the chart","The sampling frequency","The basis for subgrouping"],answer:1,hint:"What never belongs on a control chart?",steps:[{title:"Key idea",body:"The cookbook covers subgrouping, chart type, frequency, sample size and the basis for limits."},{title:"Apply",body:"Specification limits are never drawn on a control chart."}],final:"Specs are not on the chart → answer **B**",whyWrong:["Incorrect — sample size is a cookbook decision.","","Incorrect — the sampling interval is a cookbook decision.","Incorrect — the basis for subgrouping is a cookbook decision."],bookRef:"Book pp. 524–525"},{id:"sv-5-702",phase:5,topic:"5.2.1",qtype:"scenario",difficulty:2,stem:"An extrusion line changes to a new resin lot every two hours, and each lot behaves slightly differently. Where should the team take its subgroups of five?",options:["Five units spread evenly across two lots","One unit from each of the last five lots","Five consecutive units within one lot","Five units taken just after each lot change"],answer:2,hint:"Hold conditions constant inside the subgroup.",steps:[{title:"Key idea",body:"A rational subgroup is made under very similar conditions in a short time."},{title:"Apply",body:"Five consecutive units from one lot keep the lot change **between** subgroups, where it can show up."}],final:"Consecutive units within one lot → answer **C**",whyWrong:["Incorrect — spanning two lots puts lot-to-lot variation inside the subgroup.","Incorrect — one unit per lot mixes five lots inside each subgroup.","","Incorrect — sampling only at start-up gives a biased picture of the lot."],bookRef:"Book pp. 517–519"},{id:"sv-5-703",phase:5,topic:"5.2.1",qtype:"scenario",difficulty:3,stem:"Quote turnaround time is charted for three product categories (simple, standard, complex). Each daily subgroup holds one quote of each category. The chart never signals, although complex quotes are known to take much longer. What should the team do?",options:["Increase the subgroup to six quotes, two of each category","Widen the limits to 4σ so the chart is more stable","Replace the Xbar-R chart with a P chart","Form subgroups within each category, or chart each category separately"],answer:3,hint:"Where is the category difference hidden?",steps:[{title:"Key idea",body:"Putting categories inside subgroups inflates the ranges, so category differences can never appear as special causes (the book's quote-delivery example)."},{title:"Apply",body:"Subgroup within one category, or use a separate chart per category."}],final:"Keep categories out of the subgroups → answer **D**",whyWrong:["Incorrect — more units of each category still mix categories inside the subgroup.","Incorrect — wider limits would hide even more; the problem is the subgrouping.","Incorrect — turnaround time is continuous; a P chart would discard information.",""],bookRef:"Book pp. 517–519"},{id:"sv-5-704",phase:5,topic:"5.2.1",qtype:"scenario",difficulty:2,stem:"Inspectors check **five** car doors from each hour's output and count the paint blemishes on them. Every door is the same size, and a door can carry several blemishes. Which chart should be used?",options:["C chart","NP chart","P chart","Xbar-R chart"],answer:0,hint:"Defects or defectives? Constant area?",steps:[{title:"Classify",body:"Blemishes are **defects** (a door can have several); the area inspected is constant."},{title:"Select",body:"Defects with a constant sample size → **C** chart."}],final:"Defects, constant n → C → answer **A**",whyWrong:["","Incorrect — NP counts defective doors, not the blemishes on them.","Incorrect — P plots the proportion of defective doors, not the number of blemishes.","Incorrect — blemish counts are attribute data, not continuous measurements."],bookRef:"Book p. 530"},{id:"sv-5-705",phase:5,topic:"5.2.1",qtype:"scenario",difficulty:1,stem:"Every hour an operator measures the bore diameter of **four** consecutive bearings from one machine. Which chart should be used?",options:["I-MR chart","P chart","Xbar-R chart","Xbar-S chart"],answer:2,hint:"Continuous data, subgroups of four.",steps:[{title:"Classify",body:"Continuous measurements in rational subgroups of four."},{title:"Select",body:"Subgroups of 2–5 → **Xbar-R** chart."}],final:"n = 4 → Xbar-R → answer **C**",whyWrong:["Incorrect — I-MR is for subgroups of one.","Incorrect — bore diameter is continuous; a P chart is for proportions defective.","","Incorrect — Xbar-S is for subgroups of 10 or more."],bookRef:"Book p. 530"},{id:"sv-5-706",phase:5,topic:"5.2.1",qtype:"scenario",difficulty:2,stem:"A chemical plant makes one batch every two days, and **one** viscosity value is recorded per batch. Which chart should the team use?",options:["I-MR chart","P chart","Xbar-R chart","Xbar-S chart"],answer:0,hint:"Continuous data, one value per batch.",steps:[{title:"Classify",body:"Continuous data with a subgroup size of **one** (batch process)."},{title:"Select",body:"Subgroup of one → **I-MR** chart."}],final:"n = 1 → I-MR → answer **A**",whyWrong:["","Incorrect — viscosity is continuous; a P chart is for proportions defective.","Incorrect — Xbar-R needs subgroups of two or more.","Incorrect — Xbar-S is for subgroups of 10 or more."],bookRef:"Book p. 530"},{id:"sv-5-707",phase:5,topic:"5.2.1",qtype:"scenario",difficulty:2,stem:"A network probe sends **12** test pings to a core router every 15 minutes and records each round-trip latency in milliseconds. Which chart fits these data BEST?",options:["I-MR chart","U chart","Xbar-R chart","Xbar-S chart"],answer:3,hint:"Continuous data, subgroup size 12.",steps:[{title:"Classify",body:"Continuous latency, subgroups of 12."},{title:"Select",body:"Subgroups of 10 or more → **Xbar-S** chart."}],final:"n = 12 → Xbar-S → answer **D**",whyWrong:["Incorrect — I-MR is for subgroups of one; here there are 12 values per subgroup.","Incorrect — latency is continuous, not a count of defects.","Incorrect — the book's Xbar-R range is 2–5; with 12 values the range wastes information.",""],bookRef:"Book p. 530"},{id:"sv-5-708",phase:5,topic:"5.2.1",qtype:"scenario",difficulty:1,stem:"Every order processed each day is checked, and the daily volume ranges from 300 to 900 orders. An order is counted as wrong if it has **any** error. Which chart should be used?",options:["C chart","NP chart","P chart","U chart"],answer:2,hint:"Defectives with a varying n.",steps:[{title:"Classify",body:"Each order is good or bad → **defectives**; volume varies → variable n."},{title:"Select",body:"Proportion defective with variable n → **P** chart."}],final:"Defectives, variable n → P → answer **C**",whyWrong:["Incorrect — C counts defects with a constant sample size.","Incorrect — NP needs the same number of orders checked every day.","","Incorrect — U counts defects per unit; here each order is simply right or wrong."],bookRef:"Book p. 530"},{id:"sv-5-709",phase:5,topic:"5.2.1",qtype:"best-action",difficulty:2,stem:"An hourly Xbar-R chart of handle time has stayed in control for three months with no signals. The Green Belt reduced sampling to one subgroup every four hours. Was this an appropriate action?",options:["Yes, because the rate can be reduced once the process shows it stays in control","Yes, because a stable process no longer needs any sampling at all","No, because the sampling rate must never change once the chart has started","No, because reducing the rate always makes the control limits invalid"],answer:0,hint:"Start with extra samples, then reduce.",steps:[{title:"Key idea",body:"The book: take extra samples at first and reduce once the process stays in control."},{title:"Apply",body:"Three stable months justify a lower rate, while sampling continues."}],final:"Reducing after sustained control is fine → answer **A**",whyWrong:["","Incorrect — a stable process still needs monitoring; the rate is reduced, not stopped.","Incorrect — the book expects the rate to be reduced once the process stays in control.","Incorrect — limits depend on within-subgroup variation, not on how often subgroups are taken."],bookRef:"Book p. 529"},{id:"sv-5-710",phase:5,topic:"5.2.1",qtype:"best-action",difficulty:3,stem:"Monthly SLA % is recorded as **one** value per month. To use an Xbar-R chart, the Green Belt grouped each three consecutive months into a subgroup of three. Was this an appropriate action?",options:["Yes, because any three consecutive values form a rational subgroup","Yes, because an Xbar-R chart is always more sensitive than an I-MR chart","No, because the values should first be converted into a P chart","No, because months are not made under similar conditions in a short time; use an I-MR chart"],answer:3,hint:"Is a quarter a 'short time under similar conditions'?",steps:[{title:"Key idea",body:"A rational subgroup needs units made under very similar conditions in a short time."},{title:"Apply",body:"Three months span many changes; with one value per period the book's choice is I-MR."}],final:"One value per period → I-MR, not artificial subgroups → answer **D**",whyWrong:["Incorrect — consecutive values are rational only if conditions stay the same in a short time.","Incorrect — sensitivity gains only hold for genuine rational subgroups.","Incorrect — SLA % as a single monthly value is charted as individuals; the issue is the subgrouping.",""],bookRef:"Book pp. 517–519, 530"},{id:"sv-5-711",phase:5,topic:"5.2.1",qtype:"best-action",difficulty:2,stem:"The budget allows **20** handle-time measurements a day for a new chart. Which subgrouping plan is BEST?",options:["Four subgroups of five consecutive calls, spread across the day","One subgroup of 20 calls taken at noon","Twenty single calls combined into one daily subgroup","One subgroup of 20 calls taken at the end of the week"],answer:0,hint:"Small rational subgroups, taken more often.",steps:[{title:"Key idea",body:"The book: given the choice, most people take smaller subgroups more often rather than large ones rarely."},{title:"Apply",body:"Four rational subgroups of five spread over the day use the same budget and catch shifts sooner."}],final:"Small subgroups, more often → answer **A**",whyWrong:["","Incorrect — a single large subgroup at one time misses shifts during the rest of the day.","Incorrect — calls spread over a whole day are not made under similar conditions in a short time.","Incorrect — weekly sampling is far too rare and the subgroup is far too large."],bookRef:"Book pp. 517–519, 529"},{id:"sv-5-712",phase:5,topic:"5.2.1",qtype:"best-action",difficulty:3,stem:"A team wants to start a P chart of 'orders with errors' tomorrow. The two order-entry sites have not yet agreed what counts as an error. What should the team do FIRST?",options:["Collect 20 subgroups and calculate the limits","Agree one operational definition of an error for both sites","Choose between an NP chart and a P chart","Set the sampling frequency to ten times a day"],answer:1,hint:"Cookbook step: decide the measurement method and criteria.",steps:[{title:"Key idea",body:"The cookbook includes deciding the measurement method and criteria before data are collected."},{title:"Apply",body:"Without one definition, the two sites would count different things on the same chart."}],final:"Define the measurement first → answer **B**",whyWrong:["Incorrect — limits from data measured differently at each site would be meaningless.","","Incorrect — the chart type is already clear; the measurement criteria are not.","Incorrect — frequency matters, but only after the measurement itself is defined."],bookRef:"Book p. 525"},{id:"sv-5-713",phase:5,topic:"5.2.1",qtype:"best-action",difficulty:2,stem:"A team charted daily failed activations on an NP chart. Daily order volume has started to vary widely, so the Green Belt switched to a P chart. Was this an appropriate action?",options:["Yes, because a fixed-n chart can no longer be used for these counts","Yes, because the NP chart needs a constant sample size and the P chart does not","No, because an NP chart works with any sample size","No, because the data should now be charted on a U chart"],answer:1,hint:"What does NP assume about n?",steps:[{title:"Key idea",body:"NP = number defective with a **constant** n; P = proportion defective with constant or variable n."},{title:"Apply",body:"Volume now varies, so P is the right chart."}],final:"Variable n → P chart → answer **B**",whyWrong:["Incorrect — the counts can still be charted; only the chart type has to change.","","Incorrect — the NP chart requires a constant sample size.","Incorrect — failed activations are defectives, not defects, so U does not fit."],bookRef:"Book pp. 521, 530"},{id:"sv-5-714",phase:5,topic:"5.2.1",qtype:"output",difficulty:3,stem:`The sampling log for a new Xbar-R chart of shaft diameter is shown.

\`\`\`
Sampling log – Shaft diameter (mm)   Xbar-R chart, n = 5
Subgroup   Times the five shafts were taken
1          08:00  09:00  10:00  11:00  12:00
2          13:00  14:00  15:00  16:00  17:00
3          08:00  09:00  10:00  11:00  12:00   (next day)
\`\`\`

What is the MAIN problem with these subgroups?`,options:["Five shafts is too large a subgroup for an Xbar-R chart","Shafts should be measured only once a day to reduce cost","Each subgroup spans five hours, so changes during the day fall inside the subgroup","The subgroups should mix shafts from several machines"],answer:2,hint:"Rational = similar conditions in a SHORT time.",steps:[{title:"Read",body:"Each subgroup is built from one shaft per hour across five hours."},{title:"Decide",body:"Conditions can change within those hours, so special causes end up inside the subgroups; take five consecutive shafts at each sampling time instead."}],final:"Subgroups span too long a time → answer **C**",whyWrong:["Incorrect — 2 to 5 is the book's Xbar-R range, so n = 5 is fine.","Incorrect — less sampling risks missing shifts; the issue is how each subgroup is formed.","","Incorrect — mixing machines inside subgroups is exactly what rational subgrouping avoids."],bookRef:"Book pp. 517–519"},{id:"sv-5-715",phase:5,topic:"5.2.1",qtype:"output",difficulty:2,stem:`Four sampling plans are proposed for an Xbar-R chart of call-handling time. The contact centre runs three shifts.

\`\`\`
Plan  Subgroup                 When taken
A     5 consecutive calls      Every hour, all shifts
B     5 consecutive calls      08:00 only, day shift
C     5 consecutive calls      Random minute each hour, all shifts
D     5 consecutive calls      Every 2 hours, all shifts
\`\`\`

Which plan is MOST likely to give a biased chart?`,options:["Plan A","Plan B","Plan C","Plan D"],answer:1,hint:"Does the plan represent the whole population?",steps:[{title:"Read",body:"Only Plan B samples a single time slot on one shift."},{title:"Decide",body:"The book lists sampling only one shift or one time of day as biased sampling."}],final:"One shift, one time → biased → answer **B**",whyWrong:["Incorrect — hourly sampling across all shifts represents the whole process.","","Incorrect — a random minute each hour across all shifts avoids timing bias.","Incorrect — every two hours is less frequent but still covers all shifts."],bookRef:"Book pp. 517–519"},{id:"sv-5-716",phase:5,topic:"5.2.1",qtype:"output",difficulty:2,stem:`A team reviews the incident log for a provisioning KPI.

\`\`\`
Out-of-control events (incident log)
Month   Events
Apr     3
May     2
Jun     3
Jul     2
Aug     3
Sep     2
Current sampling plan: 1 subgroup at the end of each month
\`\`\`

Which conclusion is CORRECT?`,options:["Sampling is adequate because at least one subgroup is taken each month","Sampling should be reduced because events happen every month","Sampling frequency does not matter if the subgroups are rational","Sampling is far too infrequent and should be increased well above the event rate"],answer:3,hint:"Compare how often the process goes out of control with how often it is sampled.",steps:[{title:"Read",body:"Events occur every month (2–3); the plan samples once a month."},{title:"Decide",body:"The book's rule is to sample at least 10 times more often than out-of-control events, so the rate must rise sharply."}],final:"Sampling is too rare → answer **D**",whyWrong:["Incorrect — one subgroup a month is less often than the events themselves occur.","Incorrect — frequent events call for more sampling, not less.","Incorrect — rational subgroups taken too rarely still miss shifts, and the customer suffers.",""],bookRef:"Book p. 529"},{id:"sv-5-717",phase:5,topic:"5.2.1",qtype:"output",difficulty:2,stem:`This is the data collection sheet set up for a new I-MR chart of field-repair time.

\`\`\`
Data collection sheet – Repair time (h)
Date     Value
02-Sep   4.1
02-Sep   3.8
03-Sep   5.6
03-Sep   4.4
04-Sep   6.2
\`\`\`

What is the MAIN weakness of this sheet?`,options:["No stratification factors are recorded, so a signal cannot be traced to its source","The values are recorded in hours instead of minutes","An I-MR chart cannot be drawn from dates and values","Repair time should be recorded as pass or fail"],answer:0,hint:"What will the response team need when a point signals?",steps:[{title:"Read",body:"Only date and value are captured — no time of day, technician, region, shift or notes."},{title:"Decide",body:"Without stratification factors the team cannot split the data to find the cause of a signal."}],final:"Missing stratification factors → answer **A**",whyWrong:["","Incorrect — the unit of measure does not affect the chart's ability to signal.","Incorrect — an I-MR chart can be drawn, but signals could not be investigated.","Incorrect — continuous data carry more information; converting to pass/fail is worse."],bookRef:"Syllabus 5.2.1"},{id:"sv-5-718",phase:5,topic:"5.2.1",qtype:"output",difficulty:3,stem:`The billing team logs one week of invoice checks.

\`\`\`
Day   Invoices checked   Errors found
Mon   412                37
Tue   655                51
Wed   380                29
Thu   590                48
Fri   471                40
Note: one invoice can contain several errors
\`\`\`

Which chart should be used to monitor these errors?`,options:["C chart","NP chart","P chart","U chart"],answer:3,hint:"Two clues: what is counted, and is n constant?",steps:[{title:"Read",body:"Errors are counted and an invoice can hold several → **defects**. Invoices checked vary (380–655) → variable n."},{title:"Select",body:"Defects with variable sample size → **U** chart."}],final:"Defects, variable n → U → answer **D**",whyWrong:["Incorrect — C needs a constant number of invoices checked each day.","Incorrect — NP counts defective invoices with constant n; these are error counts.","Incorrect — P plots the proportion of defective invoices, not errors per invoice.",""],bookRef:"Book p. 530"},{id:"sv-5-719",phase:5,topic:"5.2.1",qtype:"output",difficulty:3,stem:`Part of a Minitab session and the sampling log are shown.

\`\`\`
Xbar-R Chart of Order Handling Time (min)   n = 5
Test Results for R Chart of Handling Time
TEST 1. One point more than 3.00 standard deviations from center line.
Test Failed at points:  6, 14, 22

Sampling log note: subgroups 6, 14 and 22 were taken between 14:00 and
14:20, during the shift handover.
\`\`\`

Which conclusion is CORRECT?`,options:["The R chart signals prove that the handling-time mean has shifted","Those subgroups span two shifts, so they are not rational; move the sampling away from handover","The R chart failures can be ignored because the Xbar chart is read first","The limits should be recalculated to include points 6, 14 and 22"],answer:1,hint:"What do the flagged subgroups have in common?",steps:[{title:"Read",body:"All three R-chart failures are subgroups taken during the handover."},{title:"Decide",body:"Each mixes two shifts' conditions, inflating the range → not rational; subgroup within one shift."}],final:"Subgroups spanning handover are not rational → answer **B**",whyWrong:["Incorrect — the R chart reflects spread inside subgroups, not a shift in the mean.","","Incorrect — the R chart is read first; the Xbar chart is not trusted until R is in control.","Incorrect — signals call for investigation, not recalculated limits."],bookRef:"Book pp. 517–519"},{id:"sv-5-720",phase:5,topic:"5.2.1",qtype:"output",difficulty:2,stem:`A team plans to freeze these limits now and start Phase II monitoring.

\`\`\`
Xbar-R Chart of Activation Time (min)
Number of subgroups = 6     Subgroup size = 5
Xbar: UCL = 42.7   CL = 38.1   LCL = 33.5
R:    UCL = 16.9   CL = 8.0    LCL = 0
No test failures.
\`\`\`

Which conclusion is CORRECT?`,options:["The limits can be frozen because no test failed","The subgroup size of 5 is too small for an Xbar-R chart","Too few subgroups have been collected; gather at least 20 before freezing the limits","The R chart's LCL of 0 shows that the data are invalid"],answer:2,hint:"How many subgroups does the book want before calculating limits?",steps:[{title:"Read",body:"Only 6 subgroups were used to estimate the limits."},{title:"Decide",body:"The book recommends at least 20 subgroups (20–25 in common practice) before limits are set."}],final:"Six subgroups are too few → answer **C**",whyWrong:["Incorrect — limits from six subgroups are unreliable even without signals.","Incorrect — 2 to 5 is the book's Xbar-R range, so n = 5 is correct.","","Incorrect — an LCL of 0 on the R chart is normal for small subgroups."],bookRef:"Book pp. 521, 525"},{id:"sv-5-721",phase:5,topic:"5.2.1",qtype:"output",difficulty:3,stem:`Subgroups of four consecutive pins are taken in turn from three machines.

\`\`\`
Xbar-R Chart of Pin Length (mm)   n = 4 consecutive pins
Subgroup   1      2      3      4      5      6      7      8      9
Machine    M1     M2     M3     M1     M2     M3     M1     M2     M3
Xbar       20.01  20.00  20.11  20.00  20.01  20.12  20.00  20.00  20.10
Xbar chart: UCL = 20.09   CL = 20.04   LCL = 19.99
TEST 1. One point more than 3.00 standard deviations from center line.
Test Failed at points:  3, 6, 9
\`\`\`

Which conclusion is CORRECT?`,options:["The signals are false alarms because each subgroup is rational","The R chart must be recalculated using only subgroups 3, 6 and 9","The limits are too narrow and should be widened to include M3","M3 runs at a different level; investigate M3 and chart each machine separately"],answer:3,hint:"Which machine do the failed points share?",steps:[{title:"Read",body:"All three Test 1 failures (points 3, 6, 9) are M3 subgroups, each with a higher mean."},{title:"Decide",body:"The difference between machines shows up between subgroups; M3 needs investigating, and one chart per machine keeps each stream clear."}],final:"M3 differs from the others → answer **D**",whyWrong:["Incorrect — rational subgroups make real between-subgroup differences visible; these are signals.","Incorrect — the failed points belong to the Xbar chart, and limits are not rebuilt from signal points.","Incorrect — widening limits to fit a signal hides a real difference between machines.",""],bookRef:"Book pp. 517–519"},{id:"sv-5-722",phase:5,topic:"5.2.1",qtype:"true-false",difficulty:1,stem:"A rational subgroup for variables data typically contains 20 to 25 units. True or False?",options:["True","False"],answer:1,hint:"Subgroup size vs number of subgroups.",steps:[{title:"Key idea",body:"Rational subgroups are small, typically 3 to 5 units."},{title:"Decide",body:"20–25 is the number of subgroups collected before limits are calculated, so the statement is false."}],final:"The statement is false → answer **False**",whyWrong:["Incorrect — 20–25 is the usual number of subgroups for setting limits; subgroups themselves are typically 3–5 units.",""],bookRef:"Book pp. 517–519"},{id:"sv-5-723",phase:5,topic:"5.2.1",qtype:"sequence",difficulty:2,stem:`Put these questions from the book's chart-selection tree in the order they are asked for **attribute** data.

- **P** — Is the sample size constant or variable?
- **Q** — Are the data continuous or attribute?
- **R** — Select the chart (C, U, NP or P)
- **S** — Are defects or defectives being counted?`,options:["Q → S → P → R","S → Q → P → R","Q → P → S → R","S → P → Q → R"],answer:0,hint:"Data type → what is counted → sample size → chart.",steps:[{title:"Key idea",body:"The tree starts with data type, then defects/defectives, then constant/variable n."},{title:"Apply",body:"Q → S → P → R."}],final:"Data type, defects/defectives, n, chart → answer **A**",whyWrong:["","Incorrect — the data type is decided before defects versus defectives.","Incorrect — defects versus defectives comes before constant versus variable n.","Incorrect — the tree starts with the data type, not with defects or defectives."],bookRef:"Book p. 530"},{id:"sv-5-724",phase:5,topic:"5.2.1",qtype:"sequence",difficulty:1,stem:`Put these continuous-data charts in order of the subgroup size they are designed for, from smallest to largest.

- **P** — Xbar-S
- **Q** — I-MR
- **R** — Xbar-R`,options:["R → Q → P","Q → R → P","Q → P → R","R → P → Q"],answer:1,hint:"1 → 2–5 → 10+.",steps:[{title:"Key idea",body:"I-MR = 1, Xbar-R = 2–5, Xbar-S = 10 or more."},{title:"Apply",body:"Q → R → P."}],final:"I-MR, Xbar-R, Xbar-S → answer **B**",whyWrong:["Incorrect — I-MR (n = 1) comes before Xbar-R (n = 2–5).","","Incorrect — Xbar-R (2–5) comes before Xbar-S (10+).","Incorrect — I-MR has the smallest subgroup, so it comes first."],bookRef:"Book p. 530"},{id:"sv-5-725",phase:5,topic:"5.2.1",qtype:"sequence",difficulty:3,stem:`Put these steps for designing the subgroups of a new Xbar-R chart in the correct order.

- **P** — Set how often a subgroup is taken
- **Q** — List the known sources of variation (shift, lot, machine)
- **R** — Decide the subgroup size
- **S** — Arrange subgroups so those sources fall between, not inside, subgroups`,options:["Q → R → S → P","S → Q → R → P","Q → S → R → P","Q → S → P → R"],answer:2,hint:"Basis for subgrouping → size → frequency.",steps:[{title:"Key idea",body:"First know the sources, then set the subgroup basis, then the size, then the frequency (size before frequency)."},{title:"Apply",body:"Q → S → R → P."}],final:"Sources, basis, size, frequency → answer **C**",whyWrong:["Incorrect — the basis for subgrouping comes before the size of each subgroup.","Incorrect — sources must be listed before they can be placed between subgroups.","","Incorrect — the book says decide the subgroup size first, then the frequency."],bookRef:"Book pp. 525, 529"}];export{e as items};
